{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "The bill would let a local school board take over as authorizer and local education agency for a commission-authorized public charter school if the board and school mutually agree in writing within 30 calendar days after the school is authorized. The board would assume the charter agreement’s rights and responsibilities, and the agreement would have to be filed with the commission as the commission directs. This option would not apply to a school whose charter agreement was renewed on appeal by the commission.",
      "rationale": "Conveys the transfer mechanism, deadline, responsibilities, and appeal-renewal exception, but omits that the eligible board must be the board of the LEA where the school is located."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "the agreement would have to be filed with the commission as the commission directs.",
      "rationale": "Conveys both mandatory filing with the commission and compliance with its prescribed manner."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "changes a reference in another provision from “a charter agreement” to “an initial charter agreement.”",
      "rationale": "Conveys the wording change but does not identify § 49-13-110(b)(1); the amendment's target is not otherwise identifiable from the summary."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "For charter renewals approved by a local board, the renewed agreement would last 10 academic years.",
      "rationale": "Conveys the local-board approval condition and required 10-academic-year renewal term."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "For renewals approved by the commission, it would last between 5 and 10 academic years, as set by commission resolution.",
      "rationale": "Conveys the commission approval condition, the five-to-ten-academic-year range, and determination by commission resolution."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "In two provisions, the bill would replace language stating that a condition applies notwithstanding certain other provisions with the word “If.”",
      "rationale": "Conveys the general deletion and replacement, but identifies neither the amended subsections nor the provisions whose override language is removed. Those details are needed to identify these otherwise unspecified textual amendments."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law.",
      "rationale": "Conveys the effective-date trigger."
    }
  ]
}
